from typing import Any, Dict, List, Optional, Protocol, Set


class CacheBackend(Protocol):
    """Storage primitives a cache implementation must provide.

    Keys and values are opaque strings. Callers that need structured values
    serialize them before reaching this layer.
    """

    def get(self, key: str) -> Optional[str]: ...

    def get_many(self, keys: List[str]) -> Dict[str, Optional[str]]: ...

    def set(self, key: str, value: str, ttl: Optional[int] = None) -> bool: ...

    def delete(self, keys: List[str]) -> int: ...

    def exists(self, key: str) -> bool: ...

    def scan(self, pattern: str) -> List[str]: ...

    def sadd(self, key: str, values: List[str]) -> int: ...

    def srem(self, key: str, values: List[str]) -> int: ...

    def smembers(self, key: str) -> Set[str]: ...

    def sismember(self, key: str, value: str) -> bool: ...

    def flush(self) -> bool: ...

    def info(self) -> Dict[str, Any]: ...
